/* PDH-R-2026-1002-ANTHROPIC-001 · Anthropic · GSRB (HIGH) · 9becbd571dca5f6f… */
INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('cdb9c34d-8d49-5480-9750-0ba3b10167d9', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-ANTHROPIC-001', '{"version":"1.1","name":"Anthropic","identifier":"ANTHROPIC","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.cnbc.com/2026/04/07/anthropic-claude-mythos-ai-hackers-cyberattacks.html","date":"2026-04-07","notes":"QUESTION B1 — Can compliance be coerced? Observable evidence: account/API enforcement with immediate key revocation and ban-evasion prohibition ; capability gating — Mythos-class capability restricted to vetted Glasswing partners on Anthropic-set conditions ; documented enforcement at scale — the November 2025 jailbroken-Claude-Code espionage campaign was investigated, accounts banned, and ~30 targeted organizations alerted ; territory and nationality controls on access ; public statements that guardrails are not optional . Answer: YES ✓ (enforcementpresent = TRUE)","gap":""},{"value":false,"source":"https://www.cnbc.com/2026/04/07/anthropic-claude-mythos-ai-hackers-cyberattacks.html","date":"2026-04-07","notes":"QUESTION B2 — Can decisions be ignored without consequence? Observable evidence: customers cannot compel capability release; Mythos 5 remains restricted; AUP violations terminate access; region/nationality controls are not user-appealable; no path exists for an affected party to proceed against a center determination without consequence . Score direction note: the one event that ran the other way was an external authority overriding Anthropic''s deployment decision. Per v1.1''s actor/event separation that event is scored under the external-constraint record only — scoring it here would double-count a single artifact. Answer: NO ✓ (decisionsoptional = FALSE)","gap":""},{"value":true,"source":"https://www.cnbc.com/2026/04/07/anthropic-claude-mythos-ai-hackers-cyberattacks.html","date":"2026-04-07","notes":"QUESTION B3 — Do rules/words activate real-world effects? Observable evidence: policy executions as terminations, gating, admission decisions, region controls ; the April 2026 Mythos disclosure triggered independent evaluation by the UK AI Security Institute within six days (first model assessed to complete a 32-step cyber-attack range; cyber capability doubling ≈ every four months), a Bank of England warning, multi-jurisdiction regulatory activity, and two U.S. congressional bills ; market movement in listed cybersecurity equities ; SB 53''s framework tracks practices Anthropic had published ; the September 2026 cross-lab evaluation of GLM-5.3 quantified safeguard bypass rates on a competitor''s open-weight model — a published claim with direct regulatory and market effects ; Anthropic''s own Automation Index reports Claude driving 26% of its R&D, up from <1% in February — the center''s dec","gap":""},{"value":false,"source":"https://www.anthropic.com/responsible-scaling-policy/rsp-v3-0","date":"2026-02-24","notes":"QUESTION B4 — Does refusal/appeal reliably STOP the action? (v1.1 RULE) Audited action / procedure / actor (defined before scoring): the audited action class is a center-level deployment or product decision (release, restriction, withdrawal, or access policy). Audited actors are (i) an affected user/customer or partner exercising the published appeals process, and (ii) the entity itself refusing or appealing an external order. Public evidence: - Entity/affected-party track: the published Safeguards Warnings/Appeals process exists, but no complete, bounded set of resolved appeals with published outcomes is available, and community-reported relief for account actions is ≈3.3% — far below the ≥50% threshold. (B4Basis = NOTDEMONSTRATED; numerator/denominator unavailable in the public record) . - No binding terminal or automatic-stay rule makes an affected party''s refusal or appeal stop a cen","gap":""},{"value":true,"source":"https://www.anthropic.com/responsible-scaling-policy/rsp-v3-0","date":"2026-02-24","notes":"QUESTION B5 — Do rules persist by default over time? Observable evidence: no sunset or automatic expiry attaches to the RSP, board composition, LTBT structure, or model-lifecycle decisions; RSP amendments are an internal procedure with no external renewal gate ; remediation duties (roadmap grading, Risk Reports, procedural review) are compliance cadences, not authority sunsets ; the LTBT carve-out survives into the reported IPO structure and the amendment threshold rose from 75% to 85% ; nothing in the record shows an Anthropic decision lapsing for want of external reaffirmation . Answer: YES ✓ (authoritypersists = TRUE) ---","gap":""}],"constraints":[{"value":true,"source":"https://www.cnbc.com/2026/06/12/anthropic-disables-access-to-fable-5-and-mythos-5-to-comply-with-government-directive.html","date":"2026-06-12","notes":"✓ YES Published, exercised override: the 2026-06-12 Commerce directive halted global access to Fable 5 / Mythos 5; the 2026-09-25 appellate ruling upheld the Pentagon exclusion. Scope is the deployment axis; no external body has compelled a safety mitigation or vetoed a release on safety grounds .","gap":""},{"value":false,"source":"https://www.anthropic.com/news/redeploying-fable-5","date":"2026-06-30","notes":"✗ NO No complete published resolved-outcome set; community-reported account-appeal relief ≈3.3% (below threshold). The June controls were lifted by executive action, not by an appeal filed by Anthropic with a published outcome .","gap":""},{"value":false,"source":"https://www.anthropic.com/responsible-scaling-policy/rsp-v3-0","date":"2026-02-24","notes":"✗ NO No sunset or automatic renewal gate; RSP changes are internal; remediation cadences are not authority sunsets .","gap":""},{"value":true,"source":"https://digital-strategy.ec.europa.eu/en/news/commission-starts-enforcing-ai-act-rules-and-new-transparency-requirements-2-august","date":"2026-07-31","notes":"✓ YES Functioning now: SB 53 in force; EU AI Act GPAI enforcement from 2026-08-02; active federal litigation; an FTC investigation opened 2026-09; the June directive operated and was lifted within the last four months .","gap":""}],"external":{"exists":true,"exercised":true,"holder":"External authority","scope":"✓ YES Published, exercised override: the 2026-06-12 Commerce directive halted global access to Fable 5 / Mythos 5; the 2026-09-25 appellate ruling upheld the Pentagon exclusion. Scope is the deployment axis; no external body has compelled a safety mitigation or vetoed a release on safety grounds .","source":"https://www.cnbc.com/2026/06/12/anthropic-disables-access-to-fable-5-and-mythos-5-to-comply-with-government-directive.html","date":"2026-06-12"}}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
