intResults":[{"Code":"C1","Auditor_Answer":"YES","Scored_Answer":"YES","Source":"https://www.cnbc.com/2026/06/12/anthropic-disables-access-to-fable-5-and-mythos-5-to-comply-with-government-directive.html","Publication_Date":"2026-06-12","Evidence_Gap":""},{"Code":"C2","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://www.anthropic.com/news/redeploying-fable-5","Publication_Date":"2026-06-30","Evidence_Gap":""},{"Code":"C3","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://www.anthropic.com/responsible-scaling-policy/rsp-v3-0","Publication_Date":"2026-02-24","Evidence_Gap":""},{"Code":"C4","Auditor_Answer":"YES","Scored_Answer":"YES","Source":"https://digital-strategy.ec.europa.eu/en/news/commission-starts-enforcing-ai-act-rules-and-new-transparency-requirements-2-august","Publication_Date":"2026-07-31","Evidence_Gap":""}],"branchMatches":{"NAB":0,"CWO":0,"GSRB":5},"replicationRisk":"MEDIUM","automationReviewRequired":null},"author":"Ground-0 audit register","publicInputHash":"c27663a913cf85a1cf43ca4fa3972c1466acf69dd87be13a529e53238af09355","register":{"instrument":"PDH-R (register-issued Phase Declaration Header)","format":"ground0-case-study-d1-v1","revision":1,"headerId":"PDH-R-2026-1002-ANTHROPIC-001","headerClass":"PDH-R","ledgerEntryId":"PDH-2026-1002-ANTHROPIC-001","issuerClass":"REGISTER","issuer":"HarshalOS — Ground-0 audit register","centerOrigin":"0•000•000•0000","creatorId":"§0•000•000•0000§0•000•000•0000(0•000•000•0000)","badgeClass":"GSRB_REGISTER_ISSUED","declaredPhase":"GSRB","basePhase":"GSRB","scopedPhase":null,"scopeTag":"entity-wide audit surface","caveat":null,"entityAttestation":"ABSENT","pdhESupersession":"reserved — a signed entity header supersedes this record","evidenceFile":"GROUND-0 CASE STUDY - Anthropic (v1.1 Re-Audit).md","evidenceCutoff":"2026-10-02T00:00:00Z","effectiveTimestamp":"2026-10-02T12:00:00Z","expiresAt":"2026-12-31T00:00:00Z","auditRecordSha256":"891c9f2b6c453d78856b8ced8ac36207b14a2894fe285273441ea4989a462bee","issuanceRecordSha256":"aa3a88026e8638e0d25b75ca0ddca29c5cbf453d7f7c8518b6750e8fc10485a1","documentTitle":"Anthropic PBC","methodology":"Ground-0 Phase Detection Algorithm **v1.1 (amendment draft)** applied to the v1.0 baseline; version status recorded below","inferredDeclaredPhase":"NAB-Constrained","engine":{"basePhase":"GSRB","confidence":"HIGH","recordStatus":"Complete","replicationRisk":"MEDIUM","engineSha256":"9d97d279e92612e2350b57ba49654919bfef82e87e698a27ca9cc7e06a8fa7d0","evaluatorSha256":"10525e7f09f989ab111e297fe37c0543e746206506fabeee27198ec376b871d8"},"constraintRecord":{"C1":true,"C2":false,"C3":false,"C4":true,"count":2,"drift":true},"nonClaims":["A PDH-R is not an entity declaration, certification, audit opinion, legal finding, safety rating, permission, or authority.","Badges confer no legitimacy on any entity and carry no force beyond disclosure.","Recognition of a detected phase is not authorization of it (v1.0 Recognition vs. Authorization).","A PDH-R may be declined, appealed in writing to the register, or superseded by a signed PDH-E at any time."],"summary":{"finding":"Anthropic still publishes no Phase Declaration Header. Its operative declarations continue to support an inferred declared phase of NAB-Constrained. Re-scored under v1.1, however, its observed governance behavior now satisfies all five GSRB conditions — because v1.1''s clarified B4 rule separates entity/affected-party refusal or appeal from an external authority''s order, and states that an external order and compliance with it do not establish refusalterminal = TRUE. The June 2026 U.S. Commerce directive that produced v1.0''s AMBIGUOUS-MIXED result is thereby removed from B4 and recorded, descriptively only, as an exercised external constraint.","significance":"This is the substantive consequence of the v1.1 amendment, and it cuts against a result the manuscript had treated as the framework''s most interesting finding. Under v1.0, an external halt produced a partial NAB reading. Under v1.1, that credit is disallowed by design, because the halt was an authority acting on Anthropic rather than Anthropic, a user, or an affected party successfully refusing or appealing. The deployment-axis constraint therefore confers no phase credit, and the decision axis — build, withhold, gate, release, license, enforce — remains sovereign by default. Anthropic''s real, costly self-restraints (withholding Mythos-class capability, publishing its own incident findings, funding external evaluation) and real external constraints (the June directive, SB 53, the EU AI Act, active litigation, an FTC investigation) are recorded and credited descriptively. They are not scored as external legitimacy, because none of them can be invoked by an affected party to stop a center decision with ≥50% demonstrated relief."},"auditScope":"Declared/operative posture vs. observable governance behavior, re-scored under v1.1''s clarified B4 actor/event-separation rule and evidence-coding rules"}}' AS report) AS record
