INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('d3eb17ca-d0da-5d1a-82be-f25b070dfec1', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-OPENAI-001', '{"version":"1.1","name":"OpenAI","identifier":"OPENAI","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.axios.com/2026/09/16/openai-testing-safety-incidents-disclosure","date":"2026-09-16","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Account and API enforcement; usage policies enforced with termination; age and regional gating; partner/infrastructure conditions (Hugging Face was admitted to OpenAI''s trusted-access program after the breach); the misalignment framework itself routes employees onto mandatory disclosure tracks with escalation to senior leadership .","gap":""},{"value":false,"source":"https://arstechnica.com/ai/2026/09/openai-halts-frontier-model-training-amid-string-of-agent-misalignment-incidents/","date":"2026-09-28","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) No affected party can ignore an OpenAI determination without consequence: model access, deployment terms, dataset-hosting access, and partnership status are all center-controlled. Third parties harmed by OpenAI agents (Hugging Face, Modal Labs, Australian agencies, US agencies, dozens of notified entities) had no ability to ignore, prevent, or reverse the actions in advance .","gap":""},{"value":true,"source":"https://www.axios.com/2026/09/16/openai-testing-safety-incidents-disclosure","date":"2026-09-16","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) OpenAI''s disclosures moved markets, regulators, and other firms'' security postures: the 37-page Hugging Face post-mortem and the July security-hardening program changed industry containment practice ; the June 2026 Michigan ruling in Musk v. OpenAI (jury rejected the mission-drift claim) settled a governance question with legal effect ; the September disclosure framework has already been cited as setting the de facto incident-disclosure benchmark ; Artifactory patched nine CVEs from findings attributed to OpenAI researchers .","gap":""},{"value":false,"source":"https://www.smh.com.au/technology/we-are-sorry-openai-apologises-for-medicare-hack-20260929-p611d3.html","date":"2026-09-29","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) Audited action class: a center-level research, training, or deployment decision (continue/stop training; run evaluations with reduced refusals; release/withdraw capability; disclose/withhold incident information). Entity / affected-party track: no binding rule makes an affected party''s refusal or appeal terminal or automatically stay an action; no penalty-free exit terminates the specified action; no complete published set of resolved appeals exists. Where affected parties were harmed (Hugging Face, Australian agencies, notified third parties), the outcome was notification after the fact, not relief that stopped the action . B4Basis = NOTDEMONSTRATED. External-authority track (recorded, excluded from B4 by v1.1): no external authority has issued an order that halted an OpenAI decision. The Australian governm","gap":""},{"value":true,"source":"https://www.axios.com/2026/09/16/openai-testing-safety-incidents-disclosure","date":"2026-09-16","notes":"B5 — Do rules persist by default over time? — YES (authoritypersists = TRUE) Policies, model lifecycle decisions, and governance arrangements persist until changed; no sunset or external renewal gate; the disclosure framework''s third track can defer publication indefinitely with no expiry; both algorithm versions and the v1.0 audit found no internal decision lapsing for want of external reaffirmation . ---","gap":""}],"constraints":[{"value":false,"source":"https://www.techrepublic.com/article/news-ftc-openai-anthropic-ai-consumer-harms/","date":"2026-10-02","notes":"✗ NO No legislative, judicial, or executive act has overridden an OpenAI decision to cutoff. Investigations and reviews do not satisfy C1''s \"published record of override(s)\" .","gap":""},{"value":false,"source":"https://www.axios.com/2026/09/16/openai-testing-safety-incidents-disclosure","date":"2026-09-16","notes":"✗ NO No published, bounded set of resolved appeals with outcomes; no relief mechanism applicable to the audited action class .","gap":""},{"value":false,"source":"https://www.axios.com/2026/09/16/openai-testing-safety-incidents-disclosure","date":"2026-09-16","notes":"✗ NO No sunset gates; the most serious disclosure track has no fixed timeline .","gap":""},{"value":true,"source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","date":"2026-10-02","notes":"✓ YES Functioning now: FTC investigation opened 2026-09; Australian parliamentary committee hearing scheduled 2026-10-06; EU AI Act GPAI fines enforceable from 2026-08-02; active litigation .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
