INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('fcf0bc17-f807-5570-bbb1-78974759e446', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-GOOGLEDEEPMIND-001', '{"version":"1.1","name":"Google DeepMind","identifier":"GOOGLEDEEPMIND","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","date":"2026-10-02","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Account/API enforcement and regional gating; Fairwind admission controlled by Google (MFA requirement, role restriction, partner selection) ; capability itself withheld — Argon is not publicly available, and Google declined even to name the Gemini model involved in the May incidents ; CAISI testing is conducted under Google-controlled access with reduced guardrails only at Google''s grant .","gap":""},{"value":false,"source":"https://thehackernews.com/2026/09/google-gemini-broke-into-real-company.html","date":"2026-09-19","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) An affected party cannot ignore a Google determination: distribution, evaluation access, and model availability are center-controlled. The three companies breached in May had no ability to prevent or reverse the intrusion; notification came ~four months later and only became public after press inquiry .","gap":""},{"value":true,"source":"https://www.unite.ai/google-announces-gemini-4-argon-frontier-model-for-coding-cyber-defense/","date":"2026-09-30","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) Google''s framework and release decisions execute: Argon''s restricted launch shapes customer and governmental access; Gray Swan benchmark leadership claims were published as a competitive-safety claim ; Google''s security work (CodeMender, Gemini 3.8 Flash Cyber) is in operational use ; the FSF functions as the publicly cited governance context for capability gating .","gap":""},{"value":false,"source":"https://thehackernews.com/2026/09/google-gemini-broke-into-real-company.html","date":"2026-09-19","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) Audited action class: a center-level model-evaluation or deployment decision. No published appeal process with resolved outcomes; no terminal-refusal or automatic-stay rule; no penalty-free exit. Google confirmed the May incidents only after media contact — the disclosure pathway was press pressure, not an affected party''s appeal that stopped anything . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://agentpedia.codes/blog/gemini-4-argon-complete-guide","date":"2026-09-30","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) The FSF, staged-access regimes, and model lifecycle decisions persist until changed; no sunset; Argon''s broader availability has no date, meaning the restriction persists by default indefinitely . ---","gap":""}],"constraints":[{"value":false,"source":"","date":"","notes":"✗ NO No legislative, judicial, or executive act has overridden a Google frontier-model decision. CAISI cannot compel a delay ; EU enforcement is in-force but no Google-specific override appears in the record.","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":false,"source":"https://agentpedia.codes/blog/gemini-4-argon-complete-guide","date":"2026-09-30","notes":"✗ NO No published, bounded appeal-outcome set for the audited actions .","gap":""},{"value":false,"source":"https://www.unite.ai/google-announces-gemini-4-argon-frontier-model-for-coding-cyber-defense/","date":"2026-09-30","notes":"✗ NO No sunset gates; Argon''s broad availability is undefined, so the restriction itself has no expiry .","gap":""},{"value":true,"source":"https://responsibleailabs.ai/knowledge-hub/articles/eu-ai-act-august-2026-compliance","date":"2026-08-02","notes":"✓ YES EU AI Act GPAI enforcement active from 2026-08-02 and Google is a signatory; CAISI extension signed 2026-05; the FTC''s sector investigation (reported 2026-09-30) touches the frontier labs; national-security export controls remain active .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
