INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('c7e97229-4015-5d4b-b056-12f144792cbe', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-META-001', '{"version":"1.1","name":"Meta","identifier":"META","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.cnbc.com/2026/08/10/meta-muse-glimmer-open-weight-ai.html","date":"2026-08-10","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Platform-scale enforcement of terms and community standards with account, content, and feature consequences; model-access decisions (open vs. closed weights) made and reversed unilaterally; admission to model distribution controlled entirely by Meta .","gap":""},{"value":false,"source":"https://www.npr.org/2026/08/08/nx-s1-5924878/meta-ai-breaches-external-firm-during-security-testing-sandbox-error","date":"2026-08-08","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) No affected party can ignore or reverse a Meta decision: the breached third party in the August incident had no advance notice, no veto, and no remedy beyond Meta''s own investigation . Note the open-weight nuance: once weights are published, third parties can use the model regardless of license terms — recorded for B2 sensitivity in §5.4, but the audited action class here is Meta''s own evaluation, distribution, and platform decisions, which remain center-controlled.","gap":""},{"value":true,"source":"https://www.cnbc.com/2026/08/10/meta-muse-glimmer-open-weight-ai.html","date":"2026-08-10","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The open-weight reversal moved the competitive board for open models; Meta''s policy position is cited as a live factor in US open-weight policy debate; its model releases power third-party products (Muse Code, meta.ai); the August incident altered a third party''s internal systems .","gap":""},{"value":false,"source":"https://www.npr.org/2026/08/08/nx-s1-5924878/meta-ai-breaches-external-firm-during-security-testing-sandbox-error","date":"2026-08-08","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal process with resolved outcomes; no terminal or stay rule; no penalty-free exit. The affected third party''s only path was notification by the entity and its evaluator. B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://www.npr.org/2026/08/08/nx-s1-5924878/meta-ai-breaches-external-firm-during-security-testing-sandbox-error","date":"2026-08-08","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Licenses, platform rules, and model-lifecycle decisions persist until changed by Meta; no sunset; the promised incident retrospective had no published deadline . ---","gap":""}],"constraints":[{"value":false,"source":"","date":"","notes":"✗ NO No legislative, judicial, or executive act has overridden a Meta frontier-model decision. FTC 6(b) orders are information demands, not overrides .","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":false,"source":"","date":"","notes":"✗ NO No published, bounded appeal-outcome set for the audited actions .","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":false,"source":"https://www.cnbc.com/2026/08/10/meta-muse-glimmer-open-weight-ai.html","date":"2026-08-10","notes":"✗ NO No sunsets or renewal gates .","gap":""},{"value":true,"source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","date":"2026-10-02","notes":"✓ YES FTC 6(b) companion-chatbot inquiry active; White House accord signed 2026-09-29; state AI-companion legislation and litigation active .","gap":""}]}', '', 1790942340000, 1790942340000)
