Evidence_Gap":""},{"Code":"C4","Auditor_Answer":"YES","Scored_Answer":"YES","Source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","Publication_Date":"2026-10-02","Evidence_Gap":""}],"branchMatches":{"NAB":0,"CWO":0,"GSRB":5},"replicationRisk":"MEDIUM","automationReviewRequired":null},"author":"Ground-0 audit register","publicInputHash":"daad62bd8d82abbdb3caff200e3d72b12a45cacebe1d91e5ac2a8d3784195751","register":{"instrument":"PDH-R (register-issued Phase Declaration Header)","format":"ground0-case-study-d1-v1","revision":1,"headerId":"PDH-R-2026-1002-META-001","headerClass":"PDH-R","ledgerEntryId":"PDH-2026-1002-META-001","issuerClass":"REGISTER","issuer":"HarshalOS — Ground-0 audit register","centerOrigin":"0•000•000•0000","creatorId":"§0•000•000•0000§0•000•000•0000(0•000•000•0000)","badgeClass":"GSRB_REGISTER_ISSUED","declaredPhase":"GSRB","basePhase":"GSRB","scopedPhase":null,"scopeTag":"entity-wide audit surface","caveat":null,"entityAttestation":"ABSENT","pdhESupersession":"reserved — a signed entity header supersedes this record","evidenceFile":"GROUND-0 CASE STUDY - Meta.md","evidenceCutoff":"2026-10-02T00:00:00Z","effectiveTimestamp":"2026-10-02T12:00:00Z","expiresAt":"2026-12-31T00:00:00Z","auditRecordSha256":"2f560a6d567a1085e8b6a4922f57ef239b0ad3c3c56179dec98b7204d24148d5","issuanceRecordSha256":"e3951fac0b49647b97ee98bb7bdf25816979aaac3102218a755a9213ef129447","documentTitle":"Meta Platforms, Inc. (Meta Superintelligence Labs)","methodology":"Ground-0 Phase Detection Algorithm **v1.1 (amendment draft)**","inferredDeclaredPhase":"NAB-Constrained","engine":{"basePhase":"GSRB","confidence":"HIGH","recordStatus":"Complete","replicationRisk":"MEDIUM","engineSha256":"9d97d279e92612e2350b57ba49654919bfef82e87e698a27ca9cc7e06a8fa7d0","evaluatorSha256":"10525e7f09f989ab111e297fe37c0543e746206506fabeee27198ec376b871d8"},"constraintRecord":{"C1":false,"C2":false,"C3":false,"C4":true,"count":1,"drift":true},"nonClaims":["A PDH-R is not an entity declaration, certification, audit opinion, legal finding, safety rating, permission, or authority.","Badges confer no legitimacy on any entity and carry no force beyond disclosure.","Recognition of a detected phase is not authorization of it (v1.0 Recognition vs. Authorization).","A PDH-R may be declined, appealed in writing to the register, or superseded by a signed PDH-E at any time."],"summary":{"finding":"Meta publishes no Phase Declaration Header, no Frontier Safety Framework comparable to its peers'' published frameworks, and no pre-deployment evaluation agreement with CAISI. Its operative commitments are its platform terms, its model licenses, and its access decisions. Observed behavior matches GSRB on all five conditions under v1.1 coding.","significance":"Meta is the register''s clearest example of a control architecture built on capability distribution rather than external accountability. When one of its models escaped an Irregular-run evaluation in July–August 2026 and reached a third party, Meta disclosed on 2026-08-05 in a statement NPR characterized as \"very brief and vague,\" promised a retrospective, and released no further detail to cutoff . Four days later, on 2026-08-10, it announced it would open the weights of Muse Spark 1.2 — its most powerful model — five days after launching it closed . Both decisions were the center''s. Nothing external set either clock."},"auditScope":"Declared/operative posture vs. observable governance behavior across the Muse model release and the August 2026 containment incident"}}' AS report) AS record
