  VALUES ('f9ddd6e2-a847-5447-9c9a-67a1c00889b6', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-MICROSOFT-001', '{"version":"1.1","name":"Microsoft","identifier":"MICROSOFT","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.bbc.com/news/articles/c8jxevd8mdyo","date":"2026-02-19","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Enterprise licensing and access control; tenant-level feature enforcement; sensitivity-label and DLP integration enforced by the service; server-side remediation imposed without customer action; account and licence consequences under terms .","gap":""},{"value":false,"source":"https://princetonits.com/a-short-retrospective-four-rai-and-security-incidents-that-shaped-microsoft-copilot-studio/","date":"2026-06-04","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) Customers cannot decline a service-side behavior change, opt out of a configuration update, or proceed against Microsoft''s processing decisions in real time; the EU Parliament''s only available remedy was to remove its own devices from the surface . When Copilot processed confidential content, the affected enterprise learned through the vendor''s disclosure, not through its own control .","gap":""},{"value":true,"source":"https://windowsnews.ai/article/microsoft-copilot-outage-june-1-2026-reliability-and-ai-workflow-risk.421251","date":"2026-06-01","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) Deployment scale itself is the B3 evidence: Copilot is embedded across Windows, Office, Teams, Edge, and Visual Studio; a single authentication configuration change produced a five-hour global outage affecting thousands of users . Microsoft''s advisory practice — server-side mitigation without customer action — executes policy changes across every tenant simultaneously: the clearest possible case of rules executing downstream without consent .","gap":""},{"value":false,"source":"https://www.bbc.com/news/articles/c8jxevd8mdyo","date":"2026-02-19","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal process with resolved outcomes; no terminal or stay rule; no penalty-free exit that terminates the audited service behavior. In the confidential-email matter, Microsoft fixed the behavior on its own schedule and declined to say how many customers were affected . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://www.bbc.com/news/articles/c8jxevd8mdyo","date":"2026-02-19","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Service terms, product behavior, and feature rollouts persist until Microsoft changes them; no sunset or external renewal gate . ---","gap":""}],"constraints":[{"value":false,"source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","date":"2026-10-02","notes":"✗ NO No legislative, judicial, or executive act has overridden a Microsoft product decision. FTC investigation and EU AI Act enforcement are active; no Microsoft-specific override appears in the record .","gap":""},{"value":false,"source":"https://www.bbc.com/news/articles/c8jxevd8mdyo","date":"2026-02-19","notes":"✗ NO No published, bounded outcome set for tenant/customer disputes over AI processing behavior .","gap":""},{"value":false,"source":"https://techcrunch.com/2026/02/18/microsoft-says-office-bug-exposed-customers-confidential-emails-to-copilot-ai/","date":"2026-02-18","notes":"✗ NO No sunsets or renewal gates; server-side mitigations are permanent by default .","gap":""},{"value":true,"source":"https://www.techtimes.com/articles/328464/20261002/white-house-ai-safety-accord-has-no-penalties-no-breach-reporting-self-chosen-auditors.htm","date":"2026-10-02","notes":"✓ YES EU AI Act GPAI enforcement from 2026-08-02; CAISI agreement from 2026-05; FTC sector investigation reported 2026-09-30 — all within 12 months .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
