INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('a5473063-7137-5b02-b874-b83af4ceb88e', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-ZAI-001', '{"version":"1.1","name":"Z.ai","identifier":"ZAI","cutoff":"2026-10-02","answers":[{"value":false,"source":"","date":"","notes":"B1 — Can compliance be coerced? — NO (enforcementpresent = FALSE) — evidence gap recorded No documented enforcement action, penalty, access revocation, or deplatforming by Z.ai against a non-compliant party was located in this run. The bounded search covered Z.ai''s public materials, the GLM-5.3 release coverage, Anthropic''s evaluation, and incident trackers. No evidence is a scoring code, not proof of the negative; the sensitivity analysis in §4.1 shows what changes if this field flips.","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":true,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"B2 — Can decisions be ignored without consequence? — YES (decisionsoptional = TRUE) GLM-5.3 is an open-weight model. After publication, no user or downstream deployer can be prevented from modifying or using it, and Z.ai itself states it will not control modification or use once weights are public . The \"selected security partners\" access regime governed only the two-week window before publication .","gap":""},{"value":true,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The limited-access decision executed: partners received controlled-environment access while the public was excluded for ~two weeks . The vulnerability program produced credited findings in real projects — samples verified against MITRE, with FreeBSD and Red Hat CVEs crediting the GLM model line and Z.ai Security . And the release''s downstream effects are documented in others'' conduct: Anthropic published a cross-lab safety evaluation of it, and sector commentary on open-weight cyber capability cites GLM-5.3 as the reference case .","gap":""},{"value":false,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal route, resolved-outcome set, terminal-refusal rule, or penalty-free exit. The audited action class — model release and weight publication — cannot be stopped by any affected party; the two-week delay was the entity''s own decision, reversible only by the entity . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"B5 — Do rules persist by default over time? — YES (authoritypersists = TRUE) No sunset or expiry mechanism; weight publication is irreversible . ---","gap":""}],"constraints":[{"value":false,"source":"https://gigazine.net/news/20260930-anthropic-warned-about-glm-5-3-risk/","date":"2026-09-30","notes":"✗ NO No legislative, judicial, or higher-authority override of a Z.ai release decision appears in the record. A competitor''s evaluation is not an override .","gap":""},{"value":false,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"✗ NO No published appeal mechanism or outcome set .","gap":""},{"value":false,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"✗ NO No sunset or renewal gate demonstrated .","gap":""},{"value":false,"source":"https://mlq.ai/news/zai-delays-glm-53-weights-after-cybersecurity-tests-show-strong-exploit-capability/","date":"2026-08-19","notes":"✗ NO The only constraint-like mechanism in the record is voluntary access restriction during the withholding window; no functioning external mechanism appears .","gap":""}]}', '', 1790942340000, 1790942340000)
