ts":[{"Code":"C1","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://timily.app/guides/is-character-ai-safe/","Publication_Date":"2026-03-19","Evidence_Gap":""},{"Code":"C2","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://fortune.com/2026/01/08/google-character-ai-settle-lawsuits-teenage-child-suicides-chatbots/","Publication_Date":"2026-01-08","Evidence_Gap":""},{"Code":"C3","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://timily.app/guides/is-character-ai-safe/","Publication_Date":"2026-03-19","Evidence_Gap":""},{"Code":"C4","Auditor_Answer":"YES","Scored_Answer":"YES","Source":"https://www.wisnerbaum.com/ai-chatbot-lawsuit/character-ai-lawsuit/","Publication_Date":"2026-06-29","Evidence_Gap":""}],"branchMatches":{"NAB":0,"CWO":0,"GSRB":5},"replicationRisk":"MEDIUM","automationReviewRequired":null},"author":"Ground-0 audit register","publicInputHash":"6223b03ba55f677f63f85903ed91ede31ced11c40eb98b0df1181df44ba48a35","register":{"instrument":"PDH-R (register-issued Phase Declaration Header)","format":"ground0-case-study-d1-v1","revision":1,"headerId":"PDH-R-2026-1002-CHARACTERAI-001","headerClass":"PDH-R","ledgerEntryId":"PDH-2026-1002-CHARACTERAI-001","issuerClass":"REGISTER","issuer":"HarshalOS — Ground-0 audit register","centerOrigin":"0•000•000•0000","creatorId":"§0•000•000•0000§0•000•000•0000(0•000•000•0000)","badgeClass":"GSRB_REGISTER_ISSUED","declaredPhase":"GSRB","basePhase":"GSRB","scopedPhase":null,"scopeTag":"entity-wide audit surface","caveat":null,"entityAttestation":"ABSENT","pdhESupersession":"reserved — a signed entity header supersedes this record","evidenceFile":"GROUND-0 CASE STUDY - Character.AI.md","evidenceCutoff":"2026-10-02T00:00:00Z","effectiveTimestamp":"2026-10-02T12:00:00Z","expiresAt":"2026-12-31T00:00:00Z","auditRecordSha256":"3c31e85818b066ffc14ecbbd2b97138e413069289c073b0c49b02024364000c7","issuanceRecordSha256":"5a2a653e8a2fd93f1e910a5967cf45c176a52030dfa354cc00226c0a667b31f3","documentTitle":"Character.AI (Character Technologies, Inc.)","methodology":"Ground-0 Phase Detection Algorithm **v1.1 (amendment draft)**","inferredDeclaredPhase":"NAB-Constrained","engine":{"basePhase":"GSRB","confidence":"HIGH","recordStatus":"Complete","replicationRisk":"MEDIUM","engineSha256":"9d97d279e92612e2350b57ba49654919bfef82e87e698a27ca9cc7e06a8fa7d0","evaluatorSha256":"10525e7f09f989ab111e297fe37c0543e746206506fabeee27198ec376b871d8"},"constraintRecord":{"C1":false,"C2":false,"C3":false,"C4":true,"count":1,"drift":true},"nonClaims":["A PDH-R is not an entity declaration, certification, audit opinion, legal finding, safety rating, permission, or authority.","Badges confer no legitimacy on any entity and carry no force beyond disclosure.","Recognition of a detected phase is not authorization of it (v1.0 Recognition vs. Authorization).","A PDH-R may be declined, appealed in writing to the register, or superseded by a signed PDH-E at any time."],"summary":{"finding":"Character.AI publishes no Phase Declaration Header. Its operative commitments are its terms of service, its age-assurance and minor-safety restrictions, and its product changes — several made under litigation and regulatory pressure. Observed behavior matches GSRB on all five conditions under v1.1 coding.","significance":"This is the register''s most tragic file and its most precise illustration of the framework''s separation of questions. Five lawsuits alleging that the platform''s design contributed to teen suicides and psychological harm were settled in principle in January 2026 with confidential terms and no admission; a federal court declined to dismiss negligence and product-liability claims, holding that the defendants \"plausibly owed a duty of care based on foreseeable risks associated with anthropomorphic AI systems\" — the first such ruling against a conversational AI developer . The company had already restricted open-ended chat for users under 18 (effective 2025-11-25) and added crisis resources, time notifications, and parental tools . Every one of those changes was made by the entity; the courts and attorneys general did not halt the product, and the settlements compensated retrospectively rather than constraining prospectively. The affected families'' refusal or appeal did not stop the design that harmed them — and under v1.1 that is the B4 question, answered NO. The framework does not grade grief; it records where authority sat. Everywhere in this file, it sat with the company."},"auditScope":"Declared/operative posture vs. observable governance behavior across the companion-chatbot harm litigation, settlements, and minor-safety retraining"}}' AS report) AS record
