INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('e77cc70d-eea2-5f4d-9772-01de82a1c46a', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-AMAZON-001', '{"version":"1.1","name":"Amazon (AWS AI platform)","identifier":"AMAZON","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://scalefactory.com/blog/2026/05/20/amazon-bedrock-six-months-of-security-and-governance-updates-worth-knowing-about/","date":"2026-05-20","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) The control plane is enforceable by design: identity, resource policies, guardrails, encrypted networking, audit logging, and the ability to suspend customer workloads . Amazon also pursued and won (temporarily) injunctive relief against a third-party agent operator, and opened internal investigations into employees — both documented exercises of enforcement capacity .","gap":""},{"value":false,"source":"https://scalefactory.com/blog/2026/05/20/amazon-bedrock-six-months-of-security-and-governance-updates-worth-knowing-about/","date":"2026-05-20","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) Customers, partners and downstream developers cannot obtain the same governed platform elsewhere at parity, cannot force release or deprecation decisions, and cannot exempt themselves from the control plane while using the service . Model-information disclosure is also structurally thin — Amazon scores no indicators in the model-information subdomain in Stanford''s index cited in the record .","gap":""},{"value":true,"source":"https://ai-analytics.wharton.upenn.edu/wharton-accountable-ai-lab/governing-ai-agents-what-the-amazon-outage-reveals-about-enterprise-risk/","date":"2026-07-10","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The audited surface produced operational, legal and political effects: an agent-related production outage with lost orders and revenue ; a federal court finding \"strong evidence\" of unauthorized access and enjoining a third party ; two CVEs in the agent SDK, the second bypassing the first fix ; a public executive position against human-in-the-loop orthodoxy ; and — the register''s strongest B3 instance anywhere — an Amazon security report that reportedly triggered government action against a third-party model provider .","gap":""},{"value":false,"source":"","date":"","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal route with resolved outcomes exists for platform decisions affecting customers or downstream users; remedies are contractual, private, and invisible. The employees who testified at the Seattle City Council and were placed under internal investigation filed an external civil-rights complaint — an appeal of sorts, with no outcome recorded at cutoff . B4Basis = NOTDEMONSTRATED.","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":true,"source":"https://scalefactory.com/blog/2026/05/20/amazon-bedrock-six-months-of-security-and-governance-updates-worth-knowing-about/","date":"2026-05-20","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Platform rules, deprecations and control-plane decisions persist until Amazon changes them; no sunset or external renewal gate appears . ---","gap":""}],"constraints":[{"value":false,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"✗ NO Nothing external has reversed or constrained an Amazon AI-surface decision. The Third-Party stay suspended a remedy Amazon obtained; it did not act against Amazon .","gap":""},{"value":false,"source":"","date":"","notes":"✗ NO No published appeal mechanism with a resolved-outcome set; the employees'' Seattle civil-rights complaint is pending with no outcome recorded .","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":false,"source":"https://scalefactory.com/blog/2026/05/20/amazon-bedrock-six-months-of-security-and-governance-updates-worth-knowing-about/","date":"2026-05-20","notes":"✗ NO No sunset or renewal gate on platform or release authority .","gap":""},{"value":false,"source":"https://scalefactory.com/blog/2026/05/20/amazon-bedrock-six-months-of-security-and-governance-updates-worth-knowing-about/","date":"2026-05-20","notes":"✗ NO No functioning constraint on the audited surface is demonstrated at cutoff .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
