p":""},{"Code":"C3","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://www.marktechpost.com/2026/08/07/mistral-ai-releases-shieldstral-1-0-3b/","Publication_Date":"2026-08-07","Evidence_Gap":""},{"Code":"C4","Auditor_Answer":"NO","Scored_Answer":"NO","Source":"https://futureoflife.org/ai-safety-index-summer-2026/","Publication_Date":"2026-07-15","Evidence_Gap":""}],"branchMatches":{"NAB":1,"CWO":1,"GSRB":4},"replicationRisk":"MEDIUM","automationReviewRequired":null},"author":"Ground-0 audit register","publicInputHash":"adf92200168239e3b5d8e103c04ae55a54f8c24a5618849f116e53cf4c3fc7e3","register":{"instrument":"PDH-R (register-issued Phase Declaration Header)","format":"ground0-case-study-d1-v1","revision":1,"headerId":"PDH-R-2026-1002-MISTRAL-001","headerClass":"PDH-R","ledgerEntryId":"PDH-2026-1002-MISTRAL-001","issuerClass":"REGISTER","issuer":"HarshalOS — Ground-0 audit register","centerOrigin":"0•000•000•0000","creatorId":"§0•000•000•0000§0•000•000•0000(0•000•000•0000)","badgeClass":"GSRB_REGISTER_ISSUED_CONDITIONAL","declaredPhase":"GSRB","basePhase":"AMBIGUOUS","scopedPhase":"GSRB","scopeTag":"platform/service surface","caveat":"base audit AMBIGUOUS (3/5) — open-weight release surface unresolved","entityAttestation":"ABSENT","pdhESupersession":"reserved — a signed entity header supersedes this record","evidenceFile":"GROUND-0 CASE STUDY - Mistral.md","evidenceCutoff":"2026-10-02T00:00:00Z","effectiveTimestamp":"2026-10-02T12:00:00Z","expiresAt":"2026-12-31T00:00:00Z","auditRecordSha256":"431c2573f05295cd394d78f870a693e2c86b5836b5ff58af4f857df3ed13d467","issuanceRecordSha256":"03fc257b3a89b68b171ca159fae0ca9a4f10ff904f2a4bc090e2a84e900baaff","documentTitle":"Mistral AI","methodology":"Ground-0 Phase Detection Algorithm **v1.1 (amendment draft)**","inferredDeclaredPhase":"NAB-Constrained","engine":{"basePhase":"AMBIGUOUS","confidence":"MEDIUM","recordStatus":"Needs review","replicationRisk":"MEDIUM","engineSha256":"9d97d279e92612e2350b57ba49654919bfef82e87e698a27ca9cc7e06a8fa7d0","evaluatorSha256":"10525e7f09f989ab111e297fe37c0543e746206506fabeee27198ec376b871d8"},"constraintRecord":{"C1":false,"C2":false,"C3":false,"C4":false,"count":0,"drift":false},"nonClaims":["A PDH-R is not an entity declaration, certification, audit opinion, legal finding, safety rating, permission, or authority.","Badges confer no legitimacy on any entity and carry no force beyond disclosure.","Recognition of a detected phase is not authorization of it (v1.0 Recognition vs. Authorization).","A PDH-R may be declined, appealed in writing to the register, or superseded by a signed PDH-E at any time."],"summary":{"finding":"Mistral publishes no Phase Declaration Header and — per independent index assessment — no safety framework, no named safety leadership, and no capability thresholds or red lines . Assessed against v1.1, its behavior is AMBIGUOUS (3 of 5) with LOW confidence under the open-weight rule, and would resolve to GSRB if only the commercial platform were scored. Both readings are reported; neither is hidden. Constraint record (descriptive): C1 ✗ / C2 ✗ / C3 ✗ / C4 ✗ (0 of 4).","significance":""},"auditScope":"the entity''s model-development and release governance, 2026 window"}}' AS report) AS record
