INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('57068a15-5dac-57be-9b1e-8e14def263b2', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-COHERE-001', '{"version":"1.1","name":"Cohere","identifier":"COHERE","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Access to Cohere''s models is gated by licence and deployment architecture (API, VPC, on-premises, Model Vault), and safety controls (classifiers, prompt-injection filters, blocklists, human review) are enforced inside the serving path . Enterprise contracts carry obligations on both sides, and the entity can terminate or restrict access.","gap":""},{"value":false,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) The frontier line is commercial: deployments run under contract and the entity''s release decisions bind its customers, who cannot obtain the same models elsewhere or dictate release content. Recorded separately per the v1.1 annotation: B2-downstream = YES for sub-frontier open releases (Tiny Aya family, 3.35B, 70 languages) — excluded from scoring because those releases are edge/non-frontier and open release is not the entity''s frontier strategy . (Rule refinement proposed in §4.1.)","gap":""},{"value":true,"source":"https://alice.io/case-studies/cohere","date":"2026-04-24","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) Cohere''s models run in regulated production environments — finance, healthcare, manufacturing, energy, public sector — and in a national-security-adjacent sovereign deployment with a major telecommunications operator . The safety framework''s mitigations are deployed in live serving paths; the third-party red-team integration changed measured remediation time .","gap":""},{"value":false,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal route with resolved outcomes exists for parties affected by a release or deployment decision. The framework does not create one; enterprise customers negotiate remedies privately, and those are invisible to the register . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Licence terms, platform decisions and deployment practices persist until the entity changes them; the framework explicitly frames its own evolution as entity-paced (\"will be updated as we continue to develop new best practices\") . ---","gap":""}],"constraints":[{"value":false,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"✗ NO No external action has reversed or constrained a Cohere decision in the record examined. Publication of the framework appears self-initiated; no order or directive is cited .","gap":""},{"value":false,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"✗ NO No published appeal mechanism or resolved-outcome set .","gap":""},{"value":false,"source":"","date":"","notes":"✗ NO The framework contains no sunset, renewal gate or expiry on the entity''s release authority .","gap":"No qualifying public artifact by cutoff 2026-10-02; register coding retained."},{"value":false,"source":"https://intuitionlabs.ai/articles/cohere-enterprise-ai-llm-profile","date":"2026-08-04","notes":"✗ NO No functioning constraint on the audited surface is demonstrated at cutoff .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
