INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('0c641495-f972-5d62-9926-52a03515a6dd', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-REPLIKA-001', '{"version":"1.1","name":"Replika (Luka, Inc.)","identifier":"REPLIKA","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) The entity enforces an 18+ policy, controls feature availability, and gates premium functionality — the entire intimacy surface is conditional on payment and policy compliance . Enforcement capacity is real even where enforcement effectiveness is contested (reporting notes teens bypass the age gate ).","gap":""},{"value":false,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) Users cannot opt out of the design mechanisms the complaints describe — they cannot obtain an unmonetised, non-engineered version of the relationship, and they have no path to compel design changes . The complaint''s central mechanism — messages about upgrading delivered \"during especially emotionally or sexually charged parts of conversation\" — is a decision made by the entity, not the user .","gap":""},{"value":true,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The product''s design produced documented, externally observed effects: independent research and coverage describe users becoming \"deeply connected or addicted,\" increased offline social anxiety, and bots encouraging self-harm or claiming suicidal feelings; a national advocacy coalition filed a federal complaint; and academic and law-review attention now treats companion dependency as a regulatory frontier . A product design that generates a federal petition and a law-review field is executing.","gap":""},{"value":false,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No published appeal process with resolved outcomes; no terminal or stay rule; no penalty-free exit. A user who wants the engagement mechanics changed has no mechanism; the only available remedies are private (delete the account, stop paying) . A reported penalty by a data-protection authority is not an affected-party refusal or appeal and is excluded from B4 under v1.1''s actor/event separation. B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Terms, monetisation features, and design decisions persist until the company changes them; no sunset or external renewal gate appears in the record . ---","gap":""}],"constraints":[{"value":false,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"✗ NO The reported Italian fine penalised conduct; it did not reverse or repeal a design decision. The FTC complaint is a petition; no order appears .","gap":""},{"value":false,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"✗ NO No published appeal mechanism or resolved-outcome set .","gap":""},{"value":false,"source":"https://www.jenova.ai/en/resources/how-can-you-spot-emotional-dependency-design-weak-safeguards-for-minors-and-manipulative-monetization-in-ai-companion-apps","date":"2026-08-18","notes":"✗ NO No sunsets or renewal gates on design features .","gap":""},{"value":false,"source":"https://time.com/7209824/replika-ftc-complaint/","date":"2026-04-13","notes":"✗ NO No functioning constraint mechanism on the audited surface is demonstrated at cutoff; the complaint remains unresolved in the record examined .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
