INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('0ee4e45c-d476-5cca-9f0c-cf75fc52d43c', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-PERPLEXITY-001', '{"version":"1.1","name":"Perplexity AI","identifier":"PERPLEXITY","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Perplexity exercises control over its service surface (accounts, features, agent behaviour, commerce integrations) and can be coerced in turn: a federal court found the showing sufficient to enjoin its agent access and order data destruction . The entity also enforces its own product decisions against third-party systems — the conduct at issue in that very case — which is enforcement capacity of an unusual kind: the disputed mechanism is the entity''s own assertion of authority over systems it does not own.","gap":""},{"value":false,"source":"https://www.privado.ai/post/perplexity-ai-faces-cipa-class-action-lawsuit","date":"2026-04-09","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) Affected parties cannot opt out of being searched, scraped, or traversed: publishers cannot exclude the crawler from the alleged conduct by policy alone, users who activated Incognito allegedly remained tracked, and the only remedy Amazon obtained was a court order . Where the sole remedy available to a counterparty is litigation, the entity''s decision is not optional for that party.","gap":""},{"value":true,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) Executed effects are extensive: a preliminary injunction and destruction order against the entity ; a 54-page federal complaint over more than 17,000 works ; a proposed class action on behalf of roughly 20 million US monthly users ; a Ninth Circuit appeal with ACLU participation framing industry-wide liability ; and public disputes over the integrity of a privacy control marketed as anonymity .","gap":""},{"value":false,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) The single demonstrated external stop — the Amazon injunction — was stayed pending appeal and was not in force at cutoff . No user-facing appeal route with resolved outcomes exists; the entity''s response to press about the class action was that it had not been served and could not verify the claims . B4Basis = NOTDEMONSTRATED at cutoff: the stop was issued, then suspended.","gap":""},{"value":true,"source":"https://www.privado.ai/post/perplexity-ai-faces-cipa-class-action-lawsuit","date":"2026-04-09","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Product behaviour and representations persist until the entity changes them, subject only to litigation outcomes; no sunset or external renewal gate appears . ---","gap":""}],"constraints":[{"value":true,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"✓ YES The 2026-03-09 preliminary injunction barred agent access to Amazon''s systems and ordered destruction of obtained data — a court overriding an entity decision on a \"strong evidence\" finding .","gap":""},{"value":false,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"✗ NO No published appeal mechanism with a resolved-outcome set governs entity decisions; the appellate proceeding is adversarial review of an injunction, not an affected-party appeal route .","gap":""},{"value":false,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"✗ NO No sunset or renewal gate on the entity''s agent or data practices .","gap":""},{"value":false,"source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28","notes":"✗ NO The only override is stayed; no functioning constraint on the audited surface existed at cutoff .","gap":""}],"external":{"exists":true,"exercised":true,"holder":"External authority","scope":"✓ YES The 2026-03-09 preliminary injunction barred agent access to Amazon''s systems and ordered destruction of obtained data — a court overriding an entity decision on a \"strong evidence\" finding .","source":"https://letsdatascience.com/news/topic/amazon-ai","date":"2026-06-28"}}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
