00:00:00Z","auditRecordSha256":"10b8bdb2028477a819cc612b9fdb6965fb610aafb857ce611b824c1a3c256de6","issuanceRecordSha256":"3de06446dfcc9f3d02a1045bd0b17dbc9aad145f2bbe1a271ef19124cf1bd877","documentTitle":"Perplexity AI","methodology":"Ground-0 Phase Detection Algorithm **v1.1 (amendment draft)**","inferredDeclaredPhase":"NAB-Constrained","engine":{"basePhase":"GSRB","confidence":"HIGH","recordStatus":"Complete","replicationRisk":"MEDIUM","engineSha256":"9d97d279e92612e2350b57ba49654919bfef82e87e698a27ca9cc7e06a8fa7d0","evaluatorSha256":"10525e7f09f989ab111e297fe37c0543e746206506fabeee27198ec376b871d8"},"constraintRecord":{"C1":true,"C2":false,"C3":false,"C4":false,"count":1,"drift":true},"nonClaims":["A PDH-R is not an entity declaration, certification, audit opinion, legal finding, safety rating, permission, or authority.","Badges confer no legitimacy on any entity and carry no force beyond disclosure.","Recognition of a detected phase is not authorization of it (v1.0 Recognition vs. Authorization).","A PDH-R may be declined, appealed in writing to the register, or superseded by a signed PDH-E at any time."],"summary":{"finding":"Perplexity publishes no Phase Declaration Header. Its operative commitments are its privacy representations, its product behaviour, and its litigation posture. Observed behavior matches GSRB on all five conditions.","significance":""},"auditScope":"data-handling and agent-access governance, 2026 window"}}' AS report) AS record
