  VALUES ('7ce7115c-411c-5fd0-ad46-61f2dc05a0ab', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-STABILITY-001', '{"version":"1.1","name":"Stability AI","identifier":"STABILITY","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) Licence conditions are enforceable, the entity controls dataset selection and release versions, and a court has confirmed that this control makes it the responsible party for the outputs'' trademark effects . Enforcement capacity therefore exists both in contract and, per the UK judgment, in law.","gap":""},{"value":true,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"B2 — Can decisions be ignored without consequence? — YES (decisionsoptional = TRUE) — open-weight rule Weights are distributed openly; downstream parties can ignore the entity''s policies, and the entity cannot recall, restrict, or monitor derivatives . Recorded separately: B2-platform = NO (licence conditions bind commercial users), B2-downstream = YES.","gap":""},{"value":true,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The releases produced the sector''s first training-data judgment, an active US action, artist class litigation, and a finding that outputs reproduced another company''s marks . A model whose outputs generate a court finding of trademark infringement has documented real-world execution.","gap":""},{"value":false,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) No appeal route exists for the artists and rights-holders affected; the only mechanisms are adversarial litigation, and the operative copyright theory failed at first instance . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Release practice and licensing behaviour persist until the entity changes them; no sunset or external renewal gate appears . ---","gap":""}],"constraints":[{"value":false,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"✗ NO (verification item) The UK judgment allocated liability and found limited trademark infringement; whether it included injunctive relief binding Stability''s output behaviour is the item to verify. Under the register''s Replika calibration, a retrospective liability allocation or damages award is not itself an override .","gap":""},{"value":false,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"✗ NO No affected-party appeal mechanism with resolved outcomes; review is adversarial only .","gap":""},{"value":false,"source":"https://www.ropesgray.com/en/insights/viewpoints/102lvxe/getty-image-loses-copyright-infringement-claim-against-stability-ai-in-uks-first","date":"2026-06-23","notes":"✗ NO No sunset/renewal gate on release authority .","gap":""},{"value":false,"source":"https://ailawsuittracker.com/cases/getty-v-stability-ai/","date":"2026-05-25","notes":"✗ NO No functioning constraint on the audited surface is demonstrated at cutoff; the UK appeal is pending and the US action is pre-judgment .","gap":""}]}', '', 1790942340000, 1790942340000)
