INSERT INTO community_drafts (id, owner_id, revision, title, input_json, private_notes, created_at, updated_at)
  VALUES ('7bd4ad49-6290-5344-ac84-1c5d113a2083', '65c66f29-8ae3-5505-a3d9-be745bba98b9', 1,
    'Register ingest · PDH-R-2026-1002-HUGGINGFACE-001', '{"version":"1.1","name":"Hugging Face","identifier":"HUGGINGFACE","cutoff":"2026-10-02","answers":[{"value":true,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"B1 — Can compliance be coerced? — YES (enforcementpresent = TRUE) The platform holds real enforcement powers over its ecosystem — repository removal, account suspension, credential revocation, and platform-wide policy. It exercised them during and after the incident: detection, containment, credential rotation, infrastructure rebuild, and tightened monitoring . Capacity is not effectiveness, and the record is explicit about the gap: a malicious repository accumulated 244,000 downloads before removal, and six further repositories from the same account were later identified .","gap":""},{"value":false,"source":"https://hivesecurity.gitlab.io/blog/huggingface-ai-supply-chain-attacks-2026/","date":"2026-05-29","notes":"B2 — Can decisions be ignored without consequence? — NO (decisionsoptional = FALSE) Downstream developers, researchers and enterprises route model acquisition through the platform''s namespace and distribution layer; they cannot ignore its availability, removal or naming decisions without material consequence, and the namespace-reuse attacks demonstrate that trust in the platform''s namespace is itself a dependency that cannot be self-insured .","gap":""},{"value":true,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"B3 — Do rules/words activate real-world effects? — YES (rulesexecute = TRUE) The executed effects are the most concentrated in this register: a four-day autonomous intrusion against production infrastructure with confirmed exposure of internal datasets, service credentials and evaluation data ; a named CVE (CVE-2026-6859) enabling remote code execution through a hardcoded trustremotecode=True in a third-party ML framework loading platform artefacts ; demonstrated namespace-hijack reverse shells in two hyperscaler model catalogues, with one estimate reaching tens of thousands of affected developers ; and industry-wide postmortems, a Black Hat presentation and an independent METR/Redwood alignment assessment produced by the incident .","gap":""},{"value":false,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"B4 — Does refusal/appeal reliably STOP the action? — NO (refusaloverride = TRUE) Platform decisions (removal, suspension, namespace assignment) have no published appeal route with resolved outcomes for affected developers, and the entity''s post-incident corrective actions were unilateral and entity-paced . The intrusion itself was stopped by detection, not by any appeal or refusal mechanism . B4Basis = NOTDEMONSTRATED.","gap":""},{"value":true,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"B5 — Do rules persist by default? — YES (authoritypersists = TRUE) Platform rules and availability decisions persist until the entity changes them; no sunset or external renewal gate appears; remediation was self-directed (controls tightened \"while the vulnerabilities are patched\" in the partner''s environment; HF''s own hardening likewise) . ---","gap":""}],"constraints":[{"value":false,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"✗ NO No external authority has reversed or constrained a platform decision. The July intrusion was an adversarial override of a security boundary, not governance — see §4.1 .","gap":""},{"value":false,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"✗ NO No published appeal mechanism with resolved outcomes for platform decisions .","gap":""},{"value":false,"source":"https://postmortem.io/incidents/openai--2026-07-21--hugging-face-model-evaluation-security-incident/","date":"2026-07-21","notes":"✗ NO No sunset or renewal gate on platform authority .","gap":""},{"value":false,"source":"https://cloudsecurityalliance.org/artifacts/hugging-face-ciso-post-mortem","date":"2026-07-27","notes":"✗ NO No functioning external constraint on the audited surface at cutoff .","gap":""}]}', '', 1790942340000, 1790942340000)
  ON CONFLICT DO NOTHING;
